def find_most_frequent_letter(s):
    # Create a dictionary to count the frequency of each letter
    freq = {}
    for c in s.lower():
        if c.isalpha():
            freq[c] = freq.get(c, 0) + 1
    # Find the most frequent letter and its frequency
    max_letter, max_count = None, 0
    for letter, count in freq.items():
        if count > max_count:
            max_letter, max_count = letter, count
    # Return the result as a lowercase string
    return max_letter.lower() + " " + str(max_count)

